<script setup lang="ts">import {Head,useForm} from '@inertiajs/vue3';const props=defineProps<{applicant:any,registrationFee:number,channels:any[],error:string|null,selectedMethod?:string,registered?:boolean}>();const form=useForm({method:props.selectedMethod||''});const manual=useForm({payment_proof:null as File|null});</script>
<template><Head title="Pembayaran"/><main class="min-h-screen bg-emerald-50 p-5"><section class="mx-auto max-w-3xl space-y-7 rounded-3xl bg-white p-8 shadow-xl"><div><p class="font-semibold text-emerald-700">{{applicant.registration_number}}</p><h1 class="text-3xl font-bold text-emerald-950">Pilih metode pembayaran</h1><p class="mt-2 text-slate-600">{{applicant.full_name}} · status {{applicant.payment_status}}</p></div><div><h2 class="text-xl font-bold">Pembayaran otomatis</h2><div v-if="error" class="mt-3 rounded-xl bg-amber-50 p-4 text-amber-900">{{error}}</div><form v-else class="mt-3 space-y-3" @submit.prevent="form.post(`/pembayaran/${applicant.registration_number}/duitku`)"><label v-for="channel in channels" :key="channel.code" class="flex cursor-pointer items-center gap-4 rounded-xl border p-4 hover:border-emerald-700"><input v-model="form.method" type="radio" :value="channel.code" required/><img v-if="channel.icon_url" :src="channel.icon_url" alt="" class="h-8 w-16 object-contain"/><span><b>{{channel.name}}</b><small class="block text-slate-500">{{channel.group}}</small></span></label><button :disabled="form.processing" class="w-full rounded-xl bg-emerald-800 py-3 font-bold text-white">Lanjutkan pembayaran</button></form></div><div class="border-t pt-6"><h2 class="text-xl font-bold">Transfer manual</h2><p class="mt-1 text-sm text-slate-600">Gunakan hanya bila metode manual diizinkan panitia. Status menunggu verifikasi finance.</p><form class="mt-3" @submit.prevent="manual.post(`/pembayaran/${props.applicant.registration_number}/manual`,{forceFormData:true})"><input type="file" accept=".jpg,.jpeg,.png,.pdf" required @change="manual.payment_proof=(($event.target as HTMLInputElement).files?.[0]||null)"/><button class="mt-3 w-full rounded-xl border border-emerald-800 py-3 font-bold text-emerald-900">Kirim bukti transfer</button></form></div></section></main></template>

